 13→  rock: 'bg-red-500/20 text-red-400',
 14→  funk: 'bg-purple-500/20 text-purple-400',
 15→  latin: 'bg-yellow-500/20 text-yellow-400',
 16→  world: 'bg-green-500/20 text-green-400',
 17→  rudiment: 'bg-cyan-500/20 text-cyan-400',
