 23→export default function Home() {
 24→  const [activeCategory, setActiveCategory] = useState<PatternCategory | 'all'>('all');
 25→  const loadPattern = usePatternStore((s) => s.loadPattern);
 26→  const setBpm = useTransportStore((s) => s.setBpm);
 27→  const stop = useTransportStore((s) => s.stop);
 28→  const router = useRouter();
 29→
 30→  const filtered = activeCategory === 'all'
 31→    ? allPatterns
 32→    : allPatterns.filter((p) => p.category === activeCategory);
 33→
 34→  const handleSelect = (patternId: string) => {
 35→    const pattern = allPatterns.find((p) => p.id === patternId);
 36→    if (!pattern) return;
 37→    stop();
 38→    loadPattern(pattern);
 39→    setBpm(pattern.defaultBpm);
 40→    router.push('/practice');
 41→  };
 42→
 43→  return (
 44→    <div className="min-h-screen">
 45→      <Header />
 46→      <main className="max-w-5xl mx-auto px-4 py-8">
 47→        <div className="mb-8">
 48→          <h1 className="text-2xl font-bold mb-2">Pattern Library</h1>
 49→          <p className="text-gray-400 text-sm">
 50→            Choose a pattern to practice. Click any pattern to load it in the practice view.
 51→          </p>
 52→        </div>
 53→
 54→        <DueForReviewBanner />
 55→
 56→        {/* Category filter */}
 57→        <div className="flex flex-wrap gap-2 mb-6">
 58→          {categories.map((cat) => (
 59→            <button
 60→              key={cat.id}
 61→              onClick={() => setActiveCategory(cat.id)}
 62→              className={`
 63→                px-3 py-1.5 rounded-lg text-sm font-medium transition-all cursor-pointer
 64→                ${activeCategory === cat.id
 65→                  ? 'bg-white text-gray-900'
 66→                  : 'bg-gray-800 text-gray-400 hover:bg-gray-700 hover:text-gray-300'
 67→                }
 68→              `}
 69→            >
 70→              {cat.label}
 71→            </button>
 72→          ))}
 73→        </div>
 74→
 75→        {/* Pattern grid */}
 76→        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
 77→          {filtered.map((pattern) => (
 78→            <button
 79→              key={pattern.id}
 80→              onClick={() => handleSelect(pattern.id)}
 81→              className="text-left bg-[#1a1d27] rounded-xl p-4 border border-gray-800
 82→                         hover:border-gray-600 hover:bg-[#1e2130] transition-all cursor-pointer group"
 83→            >
 84→              <div className="flex items-start justify-between mb-2">
 85→                <h3 className="font-semibold text-sm group-hover:text-white transition-colors">
 86→                  {pattern.name}
 87→                </h3>
 88→                <span className={`text-xs px-2 py-0.5 rounded-full ${categoryColors[pattern.category] ?? 'bg-gray-700 text-gray-400'}`}>
 89→                  {pattern.category}
 90→                </span>
 91→              </div>
 92→              <p className="text-xs text-gray-500 mb-3 line-clamp-2">
 93→                {pattern.description}
 94→              </p>
 95→              <div className="flex items-center gap-3 text-xs text-gray-500">
 96→                <span>{pattern.defaultBpm} BPM</span>
 97→                <span>{pattern.timeSignature.beats}/{pattern.timeSignature.noteValue}</span>
 98→                <span>{pattern.subdivision}</span>
 99→                <span>{pattern.tracks.length} tracks</span>
100→              </div>
101→
102→              {/* Mini grid preview */}
103→              <div className="mt-3 flex flex-col gap-0.5">
104→                {pattern.tracks.slice(0, 3).map((track, ti) => (
105→                  <div key={ti} className="flex gap-px">
106→                    {track.steps.map((step, si) => (
107→                      <div
108→                        key={si}
109→                        className={`h-1.5 flex-1 rounded-sm ${
110→                          step.active ? 'bg-gray-500' : 'bg-gray-800'
111→                        }`}
112→                      />
113→                    ))}
114→                  </div>
115→                ))}
116→              </div>
117→            </button>
118→          ))}
119→        </div>
120→
121→        {/* Keyboard shortcuts hint */}
122→        <div className="mt-12 border-t border-gray-800 pt-6">
123→          <h2 className="text-sm font-medium text-gray-400 mb-3">Keyboard Shortcuts</h2>
124→          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs text-gray-500">
125→            <div><kbd className="bg-gray-800 px-1.5 py-0.5 rounded text-gray-400">Space</kbd> Play / Pause</div>
126→            <div><kbd className="bg-gray-800 px-1.5 py-0.5 rounded text-gray-400">Esc</kbd> Stop</div>
127→            <div><kbd className="bg-gray-800 px-1.5 py-0.5 rounded text-gray-400">&uarr;</kbd> BPM +1</div>
128→            <div><kbd className="bg-gray-800 px-1.5 py-0.5 rounded text-gray-400">Shift+&uarr;</kbd> BPM +10</div>
129→          </div>
130→        </div>
131→      </main>
132→    </div>
133→  );
134→}
