  1→import { audioEngine } from './AudioEngine';
  2→
  3→export type StepCallback = (step: number, time: number) => void;
  4→
  5→export class Scheduler {
  6→  private timerId: ReturnType<typeof setTimeout> | null = null;
  7→  private nextStepTime = 0;
  8→  private currentStep = 0;
  9→  private onStep: StepCallback | null = null;
 10→  private totalSteps = 8;
 11→  private bpm = 120;
 12→  private swing = 0;
 13→  private subdivision: '8th' | '16th' | 'triplet' = '8th';
 14→  private stepsPerBar = 8;
 15→  private barsPlayed = 0;
 16→  private stepsInCurrentBar = 0;
 17→
 18→  // Callbacks for practice mode
 19→  private onBarComplete: ((barCount: number) => void) | null = null;
 20→
 21→  // External step listeners (used by live practice)
 22→  private stepListeners: StepCallback[] = [];
 23→
 24→  addStepListener(cb: StepCallback): () => void {
 25→    this.stepListeners.push(cb);
 26→    return () => {
 27→      this.stepListeners = this.stepListeners.filter((l) => l !== cb);
 28→    };
 29→  }
 30→
 31→  private readonly LOOKAHEAD_MS = 25;
 32→  private readonly SCHEDULE_AHEAD_S = 0.1;
 33→
 34→  start(
 35→    bpm: number,
 36→    totalSteps: number,
 37→    subdivision: '8th' | '16th' | 'triplet',
 38→    swing: number,
 39→    onStep: StepCallback,
 40→    onBarComplete?: (barCount: number) => void
 41→  ): void {
 42→    this.bpm = bpm;
 43→    this.totalSteps = totalSteps;
 44→    this.subdivision = subdivision;
 45→    this.swing = swing;
 46→    this.onStep = onStep;
 47→    this.onBarComplete = onBarComplete ?? null;
 48→    this.currentStep = 0;
 49→    this.barsPlayed = 0;
 50→    this.stepsInCurrentBar = 0;
 51→    this.stepsPerBar = totalSteps;
 52→
 53→    audioEngine.init();
 54→    this.nextStepTime = audioEngine.currentTime + 0.05; // small lead time
 55→    this.schedule();
 56→  }
 57→
 58→  stop(): void {
 59→    if (this.timerId !== null) {
 60→      clearTimeout(this.timerId);
 61→      this.timerId = null;
 62→    }
 63→    this.onStep = null;
 64→    this.onBarComplete = null;
 65→  }
 66→
 67→  setBpm(bpm: number): void {
 68→    this.bpm = bpm;
 69→  }
 70→
 71→  setSwing(swing: number): void {
 72→    this.swing = swing;
 73→  }
 74→
 75→  get step(): number {
 76→    return this.currentStep;
 77→  }
 78→
 79→  get bars(): number {
 80→    return this.barsPlayed;
 81→  }
 82→
 83→  private getStepDuration(): number {
 84→    const beatsPerSecond = this.bpm / 60;
 85→    switch (this.subdivision) {
 86→      case '8th':
 87→        return 1 / (beatsPerSecond * 2);
 88→      case '16th':
 89→        return 1 / (beatsPerSecond * 4);
 90→      case 'triplet':
 91→        return 1 / (beatsPerSecond * 3);
 92→    }
 93→  }
 94→
 95→  private schedule(): void {
 96→    const stepDuration = this.getStepDuration();
 97→
 98→    while (this.nextStepTime < audioEngine.currentTime + this.SCHEDULE_AHEAD_S) {
 99→      // Apply swing to even-numbered off-beat steps
100→      let swingOffset = 0;
101→      if (this.currentStep % 2 === 1 && this.swing > 0) {
102→        swingOffset = stepDuration * this.swing * 0.33;
103→      }
104→
105→      const scheduledTime = this.nextStepTime + swingOffset;
106→      this.onStep?.(this.currentStep, scheduledTime);
107→      this.stepListeners.forEach((l) => l(this.currentStep, scheduledTime));
108→
109→      // Track bar progress
110→      this.stepsInCurrentBar++;
111→      if (this.stepsInCurrentBar >= this.stepsPerBar) {
112→        this.stepsInCurrentBar = 0;
113→        this.barsPlayed++;
114→        this.onBarComplete?.(this.barsPlayed);
115→      }
116→
117→      this.nextStepTime += stepDuration;
118→      this.currentStep = (this.currentStep + 1) % this.totalSteps;
119→    }
120→
121→    this.timerId = setTimeout(() => this.schedule(), this.LOOKAHEAD_MS);
122→  }
123→}
