  5→import { Header } from '@/components/Header';
  6→import { BeatGrid } from '@/components/sequencer/BeatGrid';
  7→import { BpmControl } from '@/components/controls/BpmControl';
  8→import { TapPadPanel } from '@/components/live/TapPadPanel';
  9→import { LiveStatsPanel } from '@/components/live/LiveStatsPanel';
 10→import { LiveResultsModal } from '@/components/live/LiveResultsModal';
 11→import { ModeSelector } from '@/components/live/ModeSelector';
 12→import { TimingIndicator } from '@/components/live/TimingIndicator';
 13→import { StreakDisplay } from '@/components/live/StreakDisplay';
 14→import { BarHistoryStrip } from '@/components/live/BarHistoryStrip';
 15→import { MetronomeControls } from '@/components/live/MetronomeControls';
 16→import { DrillTimerSelector, DrillCountdown } from '@/components/live/DrillTimerControls';
 17→import { usePatternStore } from '@/lib/store/usePatternStore';
 18→import { useTransportStore, scheduler } from '@/lib/store/useTransportStore';
 19→import { useLivePracticeStore } from '@/lib/store/useLivePracticeStore';
 20→import { useLiveKeyboardHandler } from '@/lib/hooks/useLiveKeyboardHandler';
 21→import { useDrillTimer } from '@/lib/hooks/useDrillTimer';
 22→import { TapMatcher } from '@/lib/live-practice/TapMatcher';
 23→import { audioEngine } from '@/lib/audio/AudioEngine';
 24→import { findTempoFloor } from '@/lib/live-practice/tempoFloorAnalyzer';
