32→export const TapPad = React.memo(function TapPad({
33→  instrumentId,
34→  label,
35→  keyLabel,
36→  tapMatcher,
37→  isActive,
38→}: TapPadProps) {
39→  const [flash, setFlash] = useState<TimingGrade | null>(null);
40→  const flashTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);
41→
42→  const handleTap = useCallback(() => {
43→    if (!tapMatcher || !isActive) return;
44→
45→    const tapTime = audioEngine.currentTime;
46→    if (!useSettingsStore.getState().muteDrumSounds) {
47→      playInstrument(instrumentId, tapTime, 0.8, 0.8);
48→    }
49→
50→    const tapEvent = tapMatcher.processTap(tapTime, instrumentId);
51→    const store = useLivePracticeStore.getState();
52→    store.recordTap(tapEvent);
53→    if (tapEvent.matchedStep !== null) {
54→      store.setStepAccuracy(
55→        tapEvent.matchedStep,
56→        instrumentId,
57→        tapEvent.grade,
58→        tapEvent.offset
59→      );
60→    }
61→
62→    // Visual flash
63→    setFlash(tapEvent.grade);
64→    if (flashTimeout.current) clearTimeout(flashTimeout.current);
65→    flashTimeout.current = setTimeout(() => setFlash(null), 200);
66→  }, [instrumentId, tapMatcher, isActive]);
67→
68→  const padColor = instrumentPadColors[instrumentId];
69→  const flashColor = flash ? GRADE_COLORS[flash] : '';
70→
71→  return (
72→    <button
73→      onMouseDown={(e) => { e.preventDefault(); handleTap(); }}
74→      onTouchStart={(e) => { e.preventDefault(); handleTap(); }}
75→      className={`
76→        relative flex flex-col items-center justify-center
77→        w-16 h-16 sm:w-20 sm:h-20 rounded-xl border-2 cursor-pointer
78→        bg-gray-800/80 transition-all duration-75 select-none
79→        active:scale-90
80→        ${padColor}
81→        ${flash ? `${flashColor} scale-95` : ''}
82→      `}
83→    >
84→      <span className="text-xs sm:text-sm font-medium text-gray-200">{label}</span>
85→      <span className="text-[10px] text-gray-500 mt-0.5">{keyLabel}</span>
86→    </button>
87→  );
88→});
