 40→  stepAccuracies: Record<string, StepAccuracy>;
 41→  lastTapGrade: TimingGrade | null;
 42→  lastTapInstrument: InstrumentId | null;
 43→  lastTapOffset: number;
 44→  perTrackOffset: Record<string, { offset: number; grade: TimingGrade }>;
