10→export function useLiveKeyboardHandler(
11→  tapMatcher: TapMatcher | null,
12→  isActive: boolean
13→) {
14→  useEffect(() => {
15→    if (!isActive || !tapMatcher) return;
16→
17→    const handleKeyDown = (e: KeyboardEvent) => {
18→      if (e.repeat) return;
19→      if (
20→        e.target instanceof HTMLInputElement ||
21→        e.target instanceof HTMLTextAreaElement
22→      ) {
23→        return;
24→      }
25→
26→      const { keyMappings } = useLivePracticeStore.getState();
27→      const mapping = keyMappings.find((m) => m.key === e.code);
28→      if (!mapping) return;
29→
30→      e.preventDefault();
31→
32→      const tapTime = audioEngine.currentTime;
33→
34→      // Immediate audio feedback (unless muted)
35→      if (!useSettingsStore.getState().muteDrumSounds) {
36→        playInstrument(mapping.instrumentId, tapTime, 0.8, 0.8);
37→      }
38→
39→      // Process tap through matcher
40→      const tapEvent = tapMatcher.processTap(tapTime, mapping.instrumentId);
41→
42→      // Update store
43→      const store = useLivePracticeStore.getState();
44→      store.recordTap(tapEvent);
45→      if (tapEvent.matchedStep !== null) {
46→        store.setStepAccuracy(
47→          tapEvent.matchedStep,
48→          mapping.instrumentId,
49→          tapEvent.grade,
50→          tapEvent.offset
51→        );
52→      }
53→    };
54→
55→    window.addEventListener('keydown', handleKeyDown);
56→    return () => window.removeEventListener('keydown', handleKeyDown);
57→  }, [isActive, tapMatcher]);
58→}
