  6→import { audioEngine } from '../audio/AudioEngine';
  7→
  8→export const scheduler = new Scheduler();
  9→
 10→// Lazy accessors to avoid circular imports
 11→function getPatternState() {
 12→  // eslint-disable-next-line @typescript-eslint/no-require-imports
 13→  const { usePatternStore } = require('./usePatternStore');
 14→  return usePatternStore.getState() as {
 15→    currentPattern: {
 16→      tracks: Track[];
 17→      totalSteps: number;
 18→      subdivision: '8th' | '16th' | 'triplet';
 19→    };
 20→  };
 21→}
 22→
 23→function getPracticeState() {
 24→  // eslint-disable-next-line @typescript-eslint/no-require-imports
 25→  const { usePracticeStore } = require('./usePracticeStore');
 26→  return usePracticeStore as {
 27→    getState: () => {
 28→      mode: string;
 29→      tempoRampConfig: { incrementBpm: number; endBpm: number; barsPerIncrement: number };
 30→    };
 31→    setState: (state: Record<string, unknown>) => void;
 32→  };
 33→}
 34→
 35→interface TransportStore {
 36→  playState: PlayState;
 37→  bpm: number;
 38→  currentStep: number;
 39→  swing: number;
 40→
 41→  play: () => void;
 42→  pause: () => void;
 43→  stop: () => void;
 44→  setBpm: (bpm: number) => void;
 45→  setCurrentStep: (step: number) => void;
 46→  setSwing: (swing: number) => void;
 47→}
 48→
 49→export const useTransportStore = create<TransportStore>((set, get) => ({
 50→  playState: 'stopped',
 51→  bpm: 100,
 52→  currentStep: -1,
 53→  swing: 0,
 54→
 55→  play: () => {
 56→    const { currentPattern: pattern } = getPatternState();
 57→    const { bpm, swing } = get();
 58→
 59→    audioEngine.init();
 60→
 61→    const onStep = (step: number, time: number) => {
 62→      // Re-read pattern each step to pick up live edits
 63→      const { currentPattern: livePattern } = getPatternState();
 64→
 65→      // eslint-disable-next-line @typescript-eslint/no-require-imports
 66→      const { useSettingsStore } = require('./useSettingsStore');
 67→      const settings = useSettingsStore.getState();
 68→
 69→      if (!settings.mutePatternPlayback) {
 70→        livePattern.tracks.forEach((track: Track) => {
 71→          if (track.muted) return;
 72→          const s = track.steps[step];
 73→          if (s && s.active) {
 74→            playInstrument(track.instrumentId, time, s.velocity, track.volume);
 75→          }
 76→        });
 77→      }
 78→
 79→      // Metronome click
 80→      const metronomeMode = settings.metronomeMode;
 81→      if (metronomeMode !== 'off') {
 82→        const sub = livePattern.subdivision;
 83→        const stepsPerBeat = sub === '8th' ? 2 : sub === '16th' ? 4 : 3;
 84→        if (step % stepsPerBeat === 0) {
 85→          const beatInBar = step / stepsPerBeat;
 86→          let shouldClick = false;
 87→          let isDownbeat = beatInBar === 0;
 88→          switch (metronomeMode) {
 89→            case 'every-beat':
 90→              shouldClick = true;
 91→              break;
 92→            case '2-and-4':
 93→              shouldClick = beatInBar === 1 || beatInBar === 3;
 94→              isDownbeat = false;
 95→              break;
 96→            case 'one-per-bar':
 97→              shouldClick = beatInBar === 0;
 98→              break;
 99→          }
100→          if (shouldClick) {
101→            playMetronomeClick(time, isDownbeat, settings.metronomeVolume);
102→          }
103→        }
104→      }
105→
106→      // Schedule UI update synced to audio time
107→      const delayMs = Math.max(0, (time - audioEngine.currentTime) * 1000);
108→      setTimeout(() => {
109→        set({ currentStep: step });
110→      }, delayMs);
111→    };
112→
113→    const practiceStore = getPracticeState();
114→    const practiceState = practiceStore.getState();
115→    const onBarComplete = practiceState.mode === 'tempo-ramp'
116→      ? (barCount: number) => {
117→          const ps = practiceStore.getState();
118→          if (ps.mode === 'tempo-ramp' && ps.tempoRampConfig) {
119→            const config = ps.tempoRampConfig;
120→            if (barCount > 0 && barCount % config.barsPerIncrement === 0) {
121→              const currentBpm = get().bpm;
122→              const newBpm = Math.min(currentBpm + config.incrementBpm, config.endBpm);
123→              if (newBpm !== currentBpm) {
124→                set({ bpm: newBpm });
125→                scheduler.setBpm(newBpm);
126→                practiceStore.setState({ currentBpm: newBpm });
127→              }
128→            }
129→          }
130→          practiceStore.setState({ barsPlayed: barCount });
131→        }
132→      : undefined;
133→
134→    scheduler.start(bpm, pattern.totalSteps, pattern.subdivision, swing, onStep, onBarComplete);
135→    set({ playState: 'playing' });
136→  },
137→
138→  pause: () => {
139→    scheduler.stop();
140→    set({ playState: 'paused' });
141→  },
142→
143→  stop: () => {
144→    scheduler.stop();
145→    set({ playState: 'stopped', currentStep: -1 });
146→  },
147→
148→  setBpm: (bpm: number) => {
149→    const clamped = Math.max(40, Math.min(240, bpm));
150→    set({ bpm: clamped });
151→    scheduler.setBpm(clamped);
152→  },
153→
154→  setCurrentStep: (step: number) => set({ currentStep: step }),
155→
156→  setSwing: (swing: number) => {
157→    set({ swing });
158→    scheduler.setSwing(swing);
159→  },
160→}));
