 1→import { audioEngine } from './AudioEngine';
 2→
 3→export function playMetronomeClick(
 4→  time: number,
 5→  isDownbeat: boolean,
 6→  volume: number
 7→): void {
 8→  const ctx = audioEngine.context;
 9→  if (!ctx) return;
10→  const dest = audioEngine.destination;
11→
12→  const osc = ctx.createOscillator();
13→  osc.type = 'sine';
14→  osc.frequency.setValueAtTime(isDownbeat ? 1000 : 800, time);
15→
16→  const gain = ctx.createGain();
17→  gain.gain.setValueAtTime(volume * 0.5, time);
18→  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.05);
19→
20→  osc.connect(gain).connect(dest);
21→  osc.start(time);
22→  osc.stop(time + 0.05);
23→}
