### 12. Keyboard Handler: `useDrumpadKeyboard.ts`

```typescript
export function useDrumpadKeyboard() {
  const triggerPad = useDrumpadStore((s) => s.triggerPad);
  const releasePad = useDrumpadStore((s) => s.releasePad);
  const currentKit = useDrumpadStore((s) => s.currentKit);
  const setKit = useDrumpadStore((s) => s.setKit);

  useEffect(() => {
    const pads = KITS[currentKit].pads;
    const keyToPad = new Map(pads.map((p) => [p.keyCode, p.id]));

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat) return;
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

      // Kit switching with arrow keys
      if (e.code === 'ArrowLeft') {
        e.preventDefault();
        setKit(Math.max(0, currentKit - 1));
        return;
      }
      if (e.code === 'ArrowRight') {
        e.preventDefault();
        setKit(Math.min(KITS.length - 1, currentKit + 1));
        return;
      }

      const padId = keyToPad.get(e.code);
      if (!padId) return;
      e.preventDefault();
      audioEngine.init();
      triggerPad(padId);
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      const padId = keyToPad.get(e.code);
      if (!padId) return;
      releasePad(padId);
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [triggerPad, releasePad, currentKit, setKit]);
}
```

This follows the same pattern as the existing `useLiveKeyboardHandler` -- guard against `e.repeat`, skip input elements, use `e.code` for layout-independent key mapping.

### 13. `PadVoices.ts` -- Audio Implementation

This file exports:

```typescript
// The chokeable voice tracking for hi-hat groups
const activeChokeVoices = new Map<string, GainNode>();

export function playPadVoice(
  voiceId: PadVoiceId,
  time: number,
  velocity: number,
  volume: number
): void {
  // For the 9 original InstrumentIds, delegate to playInstrument
  if (isOriginalInstrument(voiceId)) {
    handleChokeGroup(voiceId, time);
    playInstrument(voiceId as InstrumentId, time, velocity, volume);
    return;
  }

  // For variant voices, synthesize directly
  const ctx = audioEngine.context;
  if (!ctx) return;
  const dest = audioEngine.destination;
  const vol = velocity * volume;

  switch (voiceId) {
    case 'kick-deep':
      playKickVariant(ctx, dest, time, vol, { startFreq: 100, bodyFreq: 50 });
      break;
    case 'kick-sub':
      playKickSub(ctx, dest, time, vol);
      break;
    case 'snare-clap':
      playClap(ctx, dest, time, vol);
      break;
    case 'snare-rimshot':
      playRimshot(ctx, dest, time, vol);
      break;
    case 'snare-sidestick':
      playSidestick(ctx, dest, time, vol);
      break;
    case 'snare-cross':
      playCrossStick(ctx, dest, time, vol);
      break;
    case 'percussion':
      playPercussion(ctx, dest, time, vol);
      break;
  }
}
```

Each variant synthesis function follows the same pattern as the existing `DrumSynth.ts` functions (create oscillators/buffers, schedule parameter changes, connect to destination). Specific designs:

- **`kick-deep`**: Same as `playKick` but `osc.frequency` starts at 100Hz (vs 150Hz), body at 50Hz (vs 80Hz), decay 0.6s
- **`kick-sub`**: Sine oscillator only at 60Hz, long decay (0.8s), no click layer
- **`snare-clap`**: Three staggered noise bursts (0ms, 15ms, 30ms) with bandpass at 1200Hz, simulating hand clap reverb
- **`snare-rimshot`**: Triangle oscillator at 250Hz, very short body (0.05s), noise component with higher highpass (2000Hz)
- **`snare-sidestick`**: Single triangle oscillator at 400Hz with 0.03s decay, no noise
- **`snare-cross`**: Bandpass-filtered noise (center 1500Hz, Q=3) with 0.1s decay, muted character
- **`percussion`**: Tom variant at 350Hz with 0.08s decay, punchy and short

**Choke group handling:**

```typescript
function handleChokeGroup(voiceId: PadVoiceId, time: number): void {
  for (const group of CHOKE_GROUPS) {
    const idx = group.indexOf(voiceId);
    if (idx === -1) continue;

    // This voice is in a choke group. Silence other voices in the group.
    for (const otherId of group) {
      if (otherId === voiceId) continue;
      const activeGain = activeChokeVoices.get(otherId);
      if (activeGain) {
        activeGain.gain.cancelScheduledValues(time);
        activeGain.gain.setValueAtTime(activeGain.gain.value, time);
        activeGain.gain.linearRampToValueAtTime(0, time + 0.005);
        activeChokeVoices.delete(otherId);
      }
    }
  }
}
```

For chokeable voices (hi-hat open), `playPadVoice` needs to wrap the voice's final gain node and register it in `activeChokeVoices`. This requires a modified version of the hi-hat synthesis that returns/registers its gain node. The cleanest approach: for voices in choke groups, create an intermediary gain node before the destination, register it, and connect the voice chain through it.

