              : 'bg-gray-800 text-gray-500 hover:bg-gray-700 border border-gray-700'
            }
          `}
          title={isLooping ? 'Loop on' : 'Loop off'}
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
