  const releasePad = useLaunchpadStore((s) => s.releasePad);

  const pack = ALL_PACKS[currentPackIndex];
  const mappings = pack.mappings[currentChain];

  // Render 4 rows of 12
  const rows: number[][] = [];
  for (let r = 0; r < 4; r++) {
    const row: number[] = [];
    for (let c = 0; c < GRID_COLS; c++) {
      row.push(r * GRID_COLS + c);
    }
    rows.push(row);
