                  className={`
                    px-3 py-1 rounded-md text-xs font-medium transition-colors
                    ${isActive
                      ? 'bg-gray-700/60 text-white'
                      : 'text-gray-500 hover:text-gray-300 hover:bg-gray-800/40'
