'use client';

import React from 'react';
import { Routine } from '@/lib/drumpad/routines';
import { PadVoiceId, KITS } from '@/lib/drumpad/types';

// Map voice IDs to colors for the beat visualization
const VOICE_COLORS: Record<string, string> = {
  kick: '#ef4444', 'kick-deep': '#ef4444', 'kick-sub': '#dc2626',
  snare: '#facc15', 'snare-clap': '#facc15', 'snare-rimshot': '#eab308',
  'snare-sidestick': '#eab308', 'snare-cross': '#d97706',
  'hihat-closed': '#22d3ee', 'hihat-open': '#06b6d4',
  'tom-high': '#c084fc', 'tom-mid': '#a855f7', 'tom-low': '#9333ea',
  crash: '#fb923c', ride: '#4ade80',
  percussion: '#a78bfa',
};

function getVoiceColor(padId: PadVoiceId): string {
  return VOICE_COLORS[padId] ?? '#9ca3af';
}

// Mini beat timeline visualization
function BeatViz({ hits, duration }: { hits: Routine['hits']; duration: number }) {
  return (
    <div className="relative h-5 bg-gray-900/60 rounded overflow-hidden">
      {hits.map((hit, i) => {
        const left = (hit.timestamp / duration) * 100;
        const color = getVoiceColor(hit.padId);
        const height = 4 + hit.velocity * 12; // 4-16px based on velocity
        return (
          <div
            key={i}
            className="absolute rounded-sm"
            style={{
              left: `${Math.min(left, 99)}%`,
              bottom: 0,
              width: '2px',
              height: `${height}px`,
              backgroundColor: color,
              opacity: 0.4 + hit.velocity * 0.5,
            }}
          />
        );
      })}
    </div>
  );
}

interface RoutineCardProps {
  routine: Routine;
  isActive: boolean;
  isPlaying: boolean;
  onLoad: () => void;
  onPlayToggle: () => void;
}

export const RoutineCard = React.memo(function RoutineCard({
  routine,
  isActive,
  isPlaying,
  onLoad,
  onPlayToggle,
}: RoutineCardProps) {
  const lastHit = routine.hits[routine.hits.length - 1];
  const duration = lastHit ? lastHit.timestamp + 0.1 : 1;
  const kitName = KITS[routine.kit]?.name ?? '';

  return (
    <button
      onClick={() => {
        if (!isActive) {
          onLoad();
        } else {
          onPlayToggle();
        }
      }}
      className={`
        w-full text-left rounded-lg border p-3 transition-all
        ${isActive
          ? 'bg-purple-500/10 border-purple-500/40'
          : 'bg-gray-800/40 border-gray-700/40 hover:bg-gray-800/70 hover:border-gray-600/50'
        }
      `}
    >
      <div className="flex items-start justify-between gap-2 mb-1.5">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className={`text-sm font-medium ${isActive ? 'text-purple-300' : 'text-gray-200'}`}>
              {routine.name}
            </span>
            <span className="text-[10px] text-gray-500 tabular-nums">{routine.bpm} BPM</span>
          </div>
          <p className="text-[11px] text-gray-500 mt-0.5 leading-tight">{routine.description}</p>
        </div>

        {/* Play indicator / kit badge */}
        <div className="flex items-center gap-1.5 shrink-0">
          <span className="text-[10px] text-gray-600 bg-gray-800 px-1.5 py-0.5 rounded">{kitName}</span>
          {isActive && (
            <div className={`w-5 h-5 rounded-full flex items-center justify-center ${isPlaying ? 'bg-green-500/20 text-green-400' : 'bg-gray-700 text-gray-400'}`}>
              {isPlaying ? (
                <svg width="8" height="8" viewBox="0 0 8 8" fill="currentColor">
                  <rect x="0" y="0" width="3" height="8" rx="0.5" />
                  <rect x="5" y="0" width="3" height="8" rx="0.5" />
                </svg>
              ) : (
                <svg width="8" height="8" viewBox="0 0 8 8" fill="currentColor">
                  <path d="M1 0.5v7l6.5-3.5z" />
                </svg>
              )}
            </div>
          )}
        </div>
      </div>

      <BeatViz hits={routine.hits} duration={duration} />
    </button>
  );
});

