 3→import React from 'react';
 4→import { usePatternStore } from '@/lib/store/usePatternStore';
 5→import { useTransportStore } from '@/lib/store/useTransportStore';
 6→import { TimingGrade } from '@/lib/live-practice/types';
 7→import { TrackRow } from './TrackRow';
 8→
 9→function getStepsPerBeat(subdivision: string): number {
10→  switch (subdivision) {
11→    case '16th': return 4;
12→    case 'triplet': return 3;
13→    default: return 2; // 8th
14→  }
15→}
16→
17→interface BeatGridProps {
18→  stepAccuracies?: Record<string, TimingGrade>;
19→}
20→
21→export function BeatGrid({ stepAccuracies }: BeatGridProps) {
22→  const currentPattern = usePatternStore((s) => s.currentPattern);
23→  const toggleStep = usePatternStore((s) => s.toggleStep);
24→  const toggleTrackMute = usePatternStore((s) => s.toggleTrackMute);
25→  const currentStep = useTransportStore((s) => s.currentStep);
26→
27→  const stepsPerBeat = getStepsPerBeat(currentPattern.subdivision);
28→
29→  return (
30→    <div className="bg-gray-900/50 rounded-xl p-4 sm:p-6 border border-gray-800">
31→      {/* Sticking labels for rudiments */}
32→      {currentPattern.sticking && (
33→        <div className="flex items-center gap-2 mb-2">
34→          <div className="w-20 sm:w-24" />
35→          <div className="flex gap-0.5 sm:gap-1">
36→            {currentPattern.sticking.map((hand, i) => (
37→              <div
38→                key={i}
39→                className={`
40→                  w-9 h-5 sm:w-10 sm:h-6 flex items-center justify-center text-xs font-bold rounded
41→                  ${hand === 'R' ? 'text-blue-400' : 'text-green-400'}
42→                `}
43→              >
44→                {hand}
45→              </div>
46→            ))}
47→          </div>
48→        </div>
49→      )}
50→
51→      {/* Beat number indicators */}
52→      <div className="flex items-center gap-2 mb-2">
53→        <div className="w-20 sm:w-24" />
54→        <div className="flex gap-0.5 sm:gap-1">
55→          {Array.from({ length: currentPattern.totalSteps }).map((_, i) => {
56→            const isDownbeat = i % stepsPerBeat === 0;
57→            const beatNumber = Math.floor(i / stepsPerBeat) + 1;
58→            return (
59→              <div
60→                key={i}
61→                className={`
62→                  w-9 h-5 sm:w-10 sm:h-6 flex items-center justify-center text-xs rounded
63→                  ${isDownbeat ? 'text-gray-400 font-bold' : 'text-gray-600'}
64→                `}
65→              >
66→                {isDownbeat ? beatNumber : i % stepsPerBeat === 1 ? '&' : ''}
67→              </div>
68→            );
69→          })}
70→        </div>
71→      </div>
72→
73→      {/* Track rows */}
74→      <div className="flex flex-col gap-1.5">
75→        {currentPattern.tracks.map((track, trackIndex) => (
76→          <TrackRow
77→            key={`${currentPattern.id}-${trackIndex}`}
78→            track={track}
79→            trackIndex={trackIndex}
80→            currentStep={currentStep}
81→            stepsPerBeat={stepsPerBeat}
82→            onToggleStep={toggleStep}
83→            onToggleMute={toggleTrackMute}
