 74→export const useLivePracticeStore = create<LivePracticeStore>((set, get) => ({
 75→  mode: 'full-kit',
 76→  focusedTrack: null,
 77→  isActive: false,
 78→
 79→  stepAccuracies: {},
 80→  lastTapGrade: null,
 81→  lastTapInstrument: null,
 82→  lastTapOffset: 0,
 83→  perTrackOffset: {},
 84→  streakBroken: false,
 85→
 86→  barHistory: [],
 87→  barHits: 0,
 88→  barTotal: 0,
 89→  currentBarIndex: 0,
 90→
 91→  drillDurationMs: null,
 92→  drillStartedAt: null,
 93→  drillRemainingMs: null,
 94→
 95→  stats: emptyStats(),
 96→  keyMappings: DEFAULT_KEY_MAPPINGS,
 97→
 98→  setMode: (mode: LiveMode) => set({ mode }),
 99→
100→  setFocusedTrack: (instrument: InstrumentId | null) => set({ focusedTrack: instrument }),
101→
102→  startSession: () => {
103→    const drillDurationMs = get().drillDurationMs;
104→    set({
105→      isActive: true,
106→      stats: emptyStats(),
107→      stepAccuracies: {},
108→      lastTapGrade: null,
109→      lastTapInstrument: null,
110→      lastTapOffset: 0,
111→      perTrackOffset: {},
112→      streakBroken: false,
113→      barHistory: [],
114→      barHits: 0,
115→      barTotal: 0,
116→      currentBarIndex: 0,
117→      drillStartedAt: drillDurationMs ? Date.now() : null,
118→      drillRemainingMs: drillDurationMs,
119→    });
120→  },
121→
122→  endSession: () => set({ isActive: false }),
123→
124→  recordTap: (tap: TapEvent) => {
125→    const stats = { ...get().stats, detailedTaps: [...get().stats.detailedTaps] };
126→    const prevStreak = stats.currentStreak;
127→    let broken = false;
128→    let barHits = get().barHits;
129→    let barTotal = get().barTotal;
130→
131→    if (tap.matchedStep !== null) {
132→      stats.totalExpected++;
133→      barTotal++;
134→
135→      stats.detailedTaps.push({
136→        step: tap.matchedStep,
137→        instrumentId: tap.instrumentId,
138→        offset: tap.offset,
139→        grade: tap.grade,
140→        barIndex: get().currentBarIndex,
141→      });
142→
143→      if (isHit(tap.grade)) {
144→        stats.totalHits++;
145→        stats.currentStreak++;
146→        barHits++;
147→        if (stats.currentStreak > stats.bestStreak) {
148→          stats.bestStreak = stats.currentStreak;
149→        }
150→      } else {
151→        stats.earlyLateCount++;
152→        if (prevStreak > 2) broken = true;
153→        stats.currentStreak = 0;
154→      }
155→
156→      switch (tap.grade) {
157→        case 'perfect': stats.perfectCount++; break;
158→        case 'great': stats.greatCount++; break;
159→        case 'good': stats.goodCount++; break;
160→      }
161→
162→      // Incremental average offset
163→      const total = stats.totalHits + stats.earlyLateCount;
164→      if (total > 0) {
165→        stats.averageOffset =
166→          ((stats.averageOffset * (total - 1)) + tap.offset) / total;
167→      }
168→    }
169→
170→    const perTrackOffset = { ...get().perTrackOffset };
171→    if (tap.matchedStep !== null) {
172→      perTrackOffset[tap.instrumentId] = { offset: tap.offset, grade: tap.grade };
173→    }
174→
175→    set({
176→      stats,
177→      lastTapGrade: tap.grade,
178→      lastTapInstrument: tap.instrumentId,
179→      lastTapOffset: tap.offset,
180→      perTrackOffset,
181→      barHits,
182→      barTotal,
183→      ...(broken ? { streakBroken: true } : {}),
184→    });
185→  },
186→
187→  recordMiss: (step: number, instrumentId: InstrumentId) => {
188→    const stats = { ...get().stats };
189→    const prevStreak = stats.currentStreak;
190→    stats.totalExpected++;
191→    stats.totalMisses++;
192→    stats.currentStreak = 0;
193→
194→    const key = `${step}-${instrumentId}`;
195→    const accuracies = { ...get().stepAccuracies };
196→    accuracies[key] = { step, instrumentId, grade: 'miss', offset: 0 };
197→
198→    set({
199→      stats,
200→      stepAccuracies: accuracies,
201→      barTotal: get().barTotal + 1,
202→      ...(prevStreak > 2 ? { streakBroken: true } : {}),
203→    });
204→  },
205→
206→  setStepAccuracy: (step: number, instrumentId: InstrumentId, grade: TimingGrade, offset: number) => {
207→    const key = `${step}-${instrumentId}`;
208→    const accuracies = { ...get().stepAccuracies };
209→    accuracies[key] = { step, instrumentId, grade, offset };
210→    set({ stepAccuracies: accuracies });
211→  },
212→
213→  resetStepAccuracies: () => set({ stepAccuracies: {} }),
214→
215→  recordBarEnd: (currentBpm?: number) => {
216→    const { barHits, barTotal, barHistory, stats, currentBarIndex } = get();
217→    if (barTotal === 0) return;
218→    const accuracy = Math.round((barHits / barTotal) * 100);
219→    const entry: BarAccuracy = { accuracy, hits: barHits, total: barTotal, bpm: currentBpm };
220→    const newHistory = [...barHistory, entry].slice(-16);
221→    const newStats = { ...stats, barHistory: [...stats.barHistory, entry] };
222→    set({ barHistory: newHistory, barHits: 0, barTotal: 0, stats: newStats, currentBarIndex: currentBarIndex + 1 });
223→  },
224→
225→  clearStreakBroken: () => set({ streakBroken: false }),
226→
227→  setDrillDuration: (ms: number | null) => set({ drillDurationMs: ms }),
228→
229→  updateDrillCountdown: (remainingMs: number) => set({ drillRemainingMs: remainingMs }),
230→}));
