  1→import { create } from 'zustand';
  2→import { PadVoiceId, RecordedHit, KITS } from '../drumpad/types';
  3→import { Routine } from '../drumpad/routines';
  4→import { audioEngine } from '../audio/AudioEngine';
  5→import { playPadVoice } from '../audio/PadVoices';
  6→
  7→interface DrumpadState {
  8→  activePads: Set<PadVoiceId>;
  9→  currentKit: number;
 10→  activeRoutineName: string | null;
 11→
 12→  // Recording
 13→  isRecording: boolean;
 14→  recordingStartTime: number | null;
 15→  recordedHits: RecordedHit[];
 16→
 17→  // Playback
 18→  isPlaying: boolean;
 19→  isLooping: boolean;
 20→  playbackSpeed: number; // 1.0 = original, 0.5 = half, 2.0 = double
 21→  playbackTimerIds: number[];
 22→
 23→  // Actions
 24→  triggerPad: (padId: PadVoiceId, velocity?: number) => void;
 25→  releasePad: (padId: PadVoiceId) => void;
 26→  setKit: (index: number) => void;
 27→  loadRoutine: (routine: Routine) => void;
 28→
 29→  startRecording: () => void;
 30→  stopRecording: () => void;
 31→  clearRecording: () => void;
 32→
 33→  startPlayback: () => void;
 34→  stopPlayback: () => void;
 35→  toggleLoop: () => void;
 36→  setPlaybackSpeed: (speed: number) => void;
 37→}
 38→
 39→export const useDrumpadStore = create<DrumpadState>()((set, get) => ({
 40→  activePads: new Set<PadVoiceId>(),
 41→  currentKit: 0,
 42→  activeRoutineName: null,
 43→
 44→  isRecording: false,
 45→  recordingStartTime: null,
 46→  recordedHits: [],
 47→
 48→  isPlaying: false,
 49→  isLooping: true,
 50→  playbackSpeed: 1.0,
 51→  playbackTimerIds: [],
 52→
 53→  triggerPad: (padId: PadVoiceId, velocity = 0.8) => {
 54→    const time = audioEngine.currentTime;
 55→    playPadVoice(padId, time, velocity, 0.8);
 56→
 57→    // Visual feedback
 58→    set((s) => ({ activePads: new Set(s.activePads).add(padId) }));
 59→    setTimeout(() => {
 60→      set((s) => {
 61→        const next = new Set(s.activePads);
 62→        next.delete(padId);
 63→        return { activePads: next };
 64→      });
 65→    }, 120);
 66→
 67→    // Record hit
 68→    const { isRecording, recordingStartTime } = get();
 69→    if (isRecording && recordingStartTime !== null) {
 70→      const timestamp = time - recordingStartTime;
 71→      set((s) => ({
 72→        recordedHits: [...s.recordedHits, { padId, timestamp, velocity }],
 73→      }));
 74→    }
 75→  },
 76→
 77→  releasePad: (padId: PadVoiceId) => {
 78→    set((s) => {
 79→      const next = new Set(s.activePads);
 80→      next.delete(padId);
 81→      return { activePads: next };
 82→    });
 83→  },
 84→
 85→  setKit: (index: number) => {
 86→    if (index >= 0 && index < KITS.length) {
 87→      set({ currentKit: index });
 88→    }
 89→  },
 90→
 91→  loadRoutine: (routine: Routine) => {
 92→    get().stopPlayback();
 93→    set({
 94→      recordedHits: routine.hits,
 95→      currentKit: routine.kit,
 96→      activeRoutineName: routine.name,
 97→      isRecording: false,
 98→      recordingStartTime: null,
 99→      playbackSpeed: 1.0,
100→    });
101→  },
102→
103→  startRecording: () => {
104→    audioEngine.init();
105→    set({
106→      isRecording: true,
107→      recordingStartTime: audioEngine.currentTime,
108→      recordedHits: [],
109→      activeRoutineName: null,
110→    });
111→    get().stopPlayback();
112→  },
113→
114→  stopRecording: () => {
115→    set({ isRecording: false });
116→  },
117→
118→  clearRecording: () => {
119→    get().stopPlayback();
120→    set({ recordedHits: [], recordingStartTime: null, activeRoutineName: null });
121→  },
122→
123→  startPlayback: () => {
124→    const { recordedHits, playbackSpeed, isLooping } = get();
125→    if (recordedHits.length === 0) return;
126→
127→    // Stop any existing playback first
128→    get().stopPlayback();
129→
130→    const lastHitTime = recordedHits[recordedHits.length - 1].timestamp;
131→    const loopDuration = Math.ceil(lastHitTime * 2) / 2 + 0.1; // pad slightly
132→
133→    const scheduleLoop = (offsetMs: number) => {
134→      const timerIds: number[] = [];
135→
136→      recordedHits.forEach((hit) => {
137→        const delayMs = (hit.timestamp / playbackSpeed) * 1000 + offsetMs;
138→        const id = window.setTimeout(() => {
139→          const time = audioEngine.currentTime;
140→          playPadVoice(hit.padId, time, hit.velocity, 0.8);
141→
142→          // Visual feedback
143→          set((s) => ({ activePads: new Set(s.activePads).add(hit.padId) }));
144→          window.setTimeout(() => {
145→            set((s) => {
146→              const next = new Set(s.activePads);
147→              next.delete(hit.padId);
148→              return { activePads: next };
149→            });
150→          }, 100);
151→        }, delayMs);
152→        timerIds.push(id);
153→      });
154→
155→      if (isLooping) {
156→        const loopMs = (loopDuration / playbackSpeed) * 1000 + offsetMs;
157→        const loopId = window.setTimeout(() => {
158→          if (get().isPlaying) {
159→            scheduleLoop(0);
160→          }
161→        }, loopMs);
162→        timerIds.push(loopId);
163→      }
164→
165→      set((s) => ({
166→        playbackTimerIds: [...s.playbackTimerIds, ...timerIds],
167→      }));
