startPlayback: () => {
  const { recordedHits, playbackSpeed, isLooping, activeRoutineName } = get();
  if (recordedHits.length === 0) return;

  // Stop any existing playback first
  get().stopPlayback();

  const lastHitTime = recordedHits[recordedHits.length - 1].timestamp;
  const loopDuration = Math.ceil(lastHitTime * 2) / 2 + 0.1; // pad slightly

  // Compute step duration for cursor tracking (only for routines)
  const activeRoutine = activeRoutineName
    ? ROUTINES.find((r) => r.name === activeRoutineName)
    : null;
  let stepDurationSec: number | null = null;
  let totalSteps = 0;
  if (activeRoutine) {
    const isTriplet = activeRoutine.name === 'Purdie Shuffle';
    const stepsPerBeat = isTriplet ? 3 : 4;
    stepDurationSec = isTriplet
      ? (60 / activeRoutine.bpm) / 3
      : (60 / activeRoutine.bpm) / 4;
    const stepsPerBar = stepsPerBeat * 4;
    const maxStep = Math.max(...recordedHits.map((h) => Math.round(h.timestamp / stepDurationSec!)));
    totalSteps = Math.ceil((maxStep + 1) / stepsPerBar) * stepsPerBar;
  }

  const scheduleLoop = (offsetMs: number) => {
    const timerIds: number[] = [];

    recordedHits.forEach((hit) => {
      const delayMs = (hit.timestamp / playbackSpeed) * 1000 + offsetMs;
      const id = window.setTimeout(() => {
        const time = audioEngine.currentTime;
        playPadVoice(hit.padId, time, hit.velocity, 0.8);

        // Visual feedback
        set((s) => ({ activePads: new Set(s.activePads).add(hit.padId) }));
        window.setTimeout(() => {
          set((s) => {
            const next = new Set(s.activePads);
            next.delete(hit.padId);
            return { activePads: next };
          });
        }, 100);
      }, delayMs);
      timerIds.push(id);
    });

    // Schedule step cursor updates for routine grid
    if (stepDurationSec !== null && totalSteps > 0) {
      for (let step = 0; step < totalSteps; step++) {
        const delayMs = (step * stepDurationSec / playbackSpeed) * 1000 + offsetMs;
        const id = window.setTimeout(() => {
          set({ playbackStep: step });
        }, delayMs);
        timerIds.push(id);
      }
    }

    if (isLooping) {
      const loopMs = (loopDuration / playbackSpeed) * 1000 + offsetMs;
      const loopId = window.setTimeout(() => {
        if (get().isPlaying) {
          scheduleLoop(0);
        }
      }, loopMs);
      timerIds.push(loopId);
    }

    set((s) => ({
      playbackTimerIds: [...s.playbackTimerIds, ...timerIds],
    }));
  };

  set({ isPlaying: true, playbackTimerIds: [], playbackStep: 0 });
  scheduleLoop(0);
},

stopPlayback: () => {
  const { playbackTimerIds } = get();
  playbackTimerIds.forEach((id) => window.clearTimeout(id));
  set({ isPlaying: false, playbackTimerIds: [], playbackStep: -1 });
},

