'use client';

import React, { useMemo } from 'react';
import { Routine } from '@/lib/drumpad/routines';
import { PadVoiceId, KITS } from '@/lib/drumpad/types';
import { useDrumpadStore } from '@/lib/store/useDrumpadStore';

// --- Voice metadata ---

const VOICE_LABELS: Record<string, string> = {
  'hihat-closed': 'HH Closed',
  'hihat-open': 'HH Open',
  ride: 'Ride',
  crash: 'Crash',
  snare: 'Snare',
  'snare-clap': 'Clap',
  'snare-rimshot': 'Rimshot',
  'snare-sidestick': 'Sidestick',
  'snare-cross': 'Cross',
  'tom-high': 'Tom Hi',
  'tom-mid': 'Tom Mid',
  'tom-low': 'Tom Lo',
  kick: 'Kick',
  'kick-deep': 'Deep Kick',
  'kick-sub': 'Sub',
  percussion: 'Perc',
};

// Tailwind bg classes per voice (matches BeatCell instrument colors)
const VOICE_BG: Record<string, string> = {
  kick: 'bg-red-500',
  'kick-deep': 'bg-red-500',
  'kick-sub': 'bg-red-600',
  snare: 'bg-yellow-400',
  'snare-clap': 'bg-yellow-400',
  'snare-rimshot': 'bg-yellow-500',
  'snare-sidestick': 'bg-yellow-500',
  'snare-cross': 'bg-amber-500',
  'hihat-closed': 'bg-cyan-400',
  'hihat-open': 'bg-cyan-300',
  'tom-high': 'bg-purple-400',
  'tom-mid': 'bg-purple-500',
  'tom-low': 'bg-purple-600',
  crash: 'bg-orange-400',
  ride: 'bg-green-400',
  percussion: 'bg-purple-400',
};

// Display order — top (cymbals) to bottom (kicks)
const VOICE_ORDER: PadVoiceId[] = [
  'hihat-closed', 'hihat-open', 'ride', 'crash',
  'snare', 'snare-clap', 'snare-rimshot', 'snare-sidestick', 'snare-cross',
  'tom-high', 'tom-mid', 'tom-low',
  'kick', 'kick-deep', 'kick-sub',
  'percussion',
];

// --- Grid data conversion ---

interface GridCell {
  active: boolean;
  velocity: number;
}

interface RoutineGridData {
  instruments: PadVoiceId[];
  totalSteps: number;
  stepsPerBeat: number;
  bars: number;
  grid: Map<PadVoiceId, GridCell[]>;
}

function routineToGrid(routine: Routine): RoutineGridData {
  // Detect triplet-based routines (Purdie Shuffle)
  const isTriplet = routine.name === 'Purdie Shuffle';
  const stepsPerBeat = isTriplet ? 3 : 4;
  const stepDuration = isTriplet
    ? (60 / routine.bpm) / 3 // triplet eighth = beat / 3
    : (60 / routine.bpm) / 4; // sixteenth = beat / 4

  // Find max step to determine total bars
  let maxStep = 0;
  const usedVoices = new Set<PadVoiceId>();

  for (const hit of routine.hits) {
    const step = Math.round(hit.timestamp / stepDuration);
    if (step > maxStep) maxStep = step;
    usedVoices.add(hit.padId);
  }

  const stepsPerBar = stepsPerBeat * 4; // 4 beats per bar
  const bars = Math.ceil((maxStep + 1) / stepsPerBar);
  const totalSteps = bars * stepsPerBar;

  // Order instruments
  const instruments = VOICE_ORDER.filter((v) => usedVoices.has(v));

  // Build grid
  const grid = new Map<PadVoiceId, GridCell[]>();
  for (const voice of instruments) {
    grid.set(
      voice,
      Array.from({ length: totalSteps }, () => ({ active: false, velocity: 0 })),
    );
  }

  for (const hit of routine.hits) {
    const step = Math.round(hit.timestamp / stepDuration);
    const row = grid.get(hit.padId);
    if (row && step >= 0 && step < totalSteps) {
      row[step] = { active: true, velocity: hit.velocity };
    }
  }

  return { instruments, totalSteps, stepsPerBeat, bars, grid };
}

// --- Component ---

interface RoutineGridProps {
  routine: Routine;
  currentStep?: number; // -1 or undefined = not playing
}

export const RoutineGrid = React.memo(function RoutineGrid({
  routine,
  currentStep,
}: RoutineGridProps) {
  const data = useMemo(() => routineToGrid(routine), [routine]);
  const currentKit = useDrumpadStore((s) => s.currentKit);

  // Build voice → key label lookup from active kit
  const keyMap = useMemo(() => {
    const map = new Map<PadVoiceId, string>();
    for (const pad of KITS[currentKit].pads) {
      map.set(pad.id, pad.keyLabel);
    }
    return map;
  }, [currentKit]);

  const stepsPerBar = data.stepsPerBeat * 4;

  return (
    <div className="bg-gray-900/50 rounded-xl p-3 sm:p-4 border border-gray-800">
      {/* Header: routine info */}
      <div className="flex items-center gap-2 mb-3">
        <span className="text-sm font-medium text-purple-300">{routine.name}</span>
        <span className="text-[10px] text-gray-500 tabular-nums">{routine.bpm} BPM</span>
        {data.stepsPerBeat === 3 && (
          <span className="text-[10px] text-amber-500/70 bg-amber-500/10 px-1.5 py-0.5 rounded">
            Triplet
          </span>
        )}
      </div>

      {/* Render each bar stacked vertically */}
      <div className="flex flex-col gap-4">
        {Array.from({ length: data.bars }, (_, barIndex) => {
          const barStart = barIndex * stepsPerBar;
          const barEnd = barStart + stepsPerBar;
          return (
            <div key={barIndex} className="overflow-x-auto">
              <div className="inline-flex flex-col gap-0.5 min-w-fit">
                {/* Bar label + beat numbers */}
                <div className="flex items-center">
                  <div className="w-20 sm:w-24 shrink-0 text-[10px] text-gray-600 pr-1">
                    Bar {barIndex + 1}
                  </div>
                  <div className="flex gap-px">
                    {Array.from({ length: stepsPerBar }, (_, i) => {
                      const isDownbeat = i % data.stepsPerBeat === 0;
                      const beatInBar = Math.floor(i / data.stepsPerBeat) + 1;
                      return (
                        <div
                          key={i}
                          className={`
                            w-7 h-4 sm:w-8 sm:h-5 flex items-center justify-center text-[10px]
                            ${isDownbeat ? 'text-gray-400 font-bold' : 'text-gray-700'}
                          `}
                        >
                          {isDownbeat ? beatInBar : ''}
                        </div>
                      );
                    })}
                  </div>
                </div>

                {/* Instrument rows for this bar */}
                {data.instruments.map((voice) => {
                  const fullRow = data.grid.get(voice)!;
                  const bg = VOICE_BG[voice] ?? 'bg-gray-400';
                  const key = keyMap.get(voice);
                  return (
                    <div key={voice} className="flex items-center">
                      <div className="w-20 sm:w-24 shrink-0 flex items-center gap-1 pr-1">
                        {key && (
                          <span className="text-[9px] text-gray-600 bg-gray-800 rounded px-1 py-px font-mono leading-none">
                            {key}
                          </span>
                        )}
                        <span className="text-[11px] sm:text-xs text-gray-400 truncate">
                          {VOICE_LABELS[voice] ?? voice}
                        </span>
                      </div>
                      <div className="flex gap-px">
                        {Array.from({ length: stepsPerBar }, (_, i) => {
                          const stepIndex = barStart + i;
                          const cell = fullRow[stepIndex];
                          const isDownbeat = i % data.stepsPerBeat === 0;
                          const isCurrent = currentStep !== undefined && currentStep >= 0 && currentStep === stepIndex;
                          return (
                            <div
                              key={i}
                              className={`
                                w-7 h-7 sm:w-8 sm:h-8 rounded-sm border transition-all duration-75
                                ${isDownbeat ? 'border-gray-600' : 'border-gray-700/50'}
                                ${cell.active ? bg : isDownbeat ? 'bg-gray-800/80' : 'bg-gray-800/40'}
                                ${isCurrent ? 'ring-2 ring-white/80 scale-105' : ''}
                              `}
                              style={cell.active ? { opacity: 0.5 + cell.velocity * 0.5 } : undefined}
                            />
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
});

