          <span className="text-[10px] text-amber-500/70 bg-amber-500/10 px-1.5 py-0.5 rounded">
            Triplet
          </span>
        )}
      </div>

      <div className="inline-flex flex-col gap-0.5 min-w-fit">
        {/* Beat numbers */}
        <div className="flex items-center">
          <div className="w-16 sm:w-20 shrink-0" />
          <div className="flex gap-px">
            {Array.from({ length: data.totalSteps }, (_, i) => {
              const isDownbeat = i % data.stepsPerBeat === 0;
              const beatInBar = Math.floor((i % (data.stepsPerBeat * 4)) / data.stepsPerBeat) + 1;
              const isBarStart = i % (data.stepsPerBeat * 4) === 0;
              return (
                <div
                  key={i}
                  className={`
                    w-7 h-4 sm:w-8 sm:h-5 flex items-center justify-center text-[10px]
                    ${isBarStart ? 'ml-1 first:ml-0' : ''}
                    ${isDownbeat ? 'text-gray-400 font-bold' : 'text-gray-700'}
                  `}
                >
                  {isDownbeat ? beatInBar : ''}
                </div>
              );
            })}
          </div>
        </div>

        {/* Instrument rows */}
        {data.instruments.map((voice) => {
          const row = data.grid.get(voice)!;
          const bg = VOICE_BG[voice] ?? 'bg-gray-400';
          return (
            <div key={voice} className="flex items-center">
              <div className="w-16 sm:w-20 shrink-0 text-[11px] sm:text-xs text-gray-400 truncate pr-1">
                {VOICE_LABELS[voice] ?? voice}
              </div>
              <div className="flex gap-px">
                {row.map((cell, i) => {
                  const isDownbeat = i % data.stepsPerBeat === 0;
                  const isBarStart = i % (data.stepsPerBeat * 4) === 0;
                  const isCurrent = currentStep !== undefined && currentStep >= 0 && currentStep === i;
                  return (
                    <div
                      key={i}
                      className={`
                        w-7 h-7 sm:w-8 sm:h-8 rounded-sm border transition-all duration-75
                        ${isBarStart ? 'ml-1 first:ml-0' : ''}
                        ${isDownbeat ? 'border-gray-600' : 'border-gray-700/50'}
                        ${cell.active ? bg : isDownbeat ? 'bg-gray-800/80' : 'bg-gray-800/40'}
                        ${isCurrent ? 'ring-2 ring-white/80 scale-105' : ''}
                      `}
                      style={cell.active ? { opacity: 0.5 + cell.velocity * 0.5 } : undefined}
                    />
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
});
